```json
{
  "analysis": "CSS file created successfully. Now I need to create the main visualization.js file with D3.js logic. This is the most complex part and will include:
1. Loading the CSV data
2. Creating the bubble chart with force simulation
3. Coloring bubbles by sector
4. Sizing bubbles by market cap
5. Adding labels and tooltips
6. Creating the data table
7. Implementing interactivity between chart and table",
  "plan": "Create visualization.js with comprehensive D3.js logic to:
1. Load stock-descriptions.csv
2. Parse and filter the data (exclude ETFs without market cap)
3. Set up color scale for sectors
4. Create force simulation with forceX, forceY for sector clustering and forceCollide for no overlap
5. Create bubble chart with circles sized by market cap
6. Add labels (ticker symbols) inside bubbles
7. Add tooltips on hover
8. Create legend for sectors
9. Populate the data table
10. Implement click interactivity to link bubbles and table rows",
  "commands": [
    {
      "keystrokes": "cat > /root/output/js/visualization.js << 'EOF'
const margin = { top: 20, right: 20, bottom: 20, left: 20 };
const width = document.getElementById('bubble-chart').clientWidth - margin.left - margin.right;
const height = 600 - margin.top - margin.bottom;

const svg = d3.select('#bubble-chart')
    .attr('width', width + margin.left + margin.right)
    .attr('height', height + margin.top + margin.bottom)
    .append('g')
    .attr('transform', `translate(${margin.left},${margin.top})`);

const tooltip = d3.select('#tooltip');

let stocks = [];
let simulation;

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Parse numeric fields
    stocks = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector,
        name: d['full name'],
        marketCap: parseFloat(d.marketCap) || null,
        country: d.country,
        website: d.website,
        returnOnEquity: parseFloat(d.returnOnEquity) || null,
        revenuePerShare: parseFloat(d.revenuePerShare) || null,
        bookValue: parseFloat(d.bookValue) || null,
        yield: parseFloat(d.yield) || null,
        beta: parseFloat(d.beta) || null
    })).filter(d => d.ticker && d.sector && d.name);

    // Filter out stocks without market cap (ETFs) for bubble chart, but keep for table
    const stocksWithMarketCap = stocks.filter(d => d.marketCap !== null);
    const etfs = stocks.filter(d => d.marketCap === null);

    // Create visualization
    createBubbleChart(stocksWithMarketCap, etfs);
    createTable(stocks);
}).catch(error => {
    console.error('Error loading data:', error);
});

function createBubbleChart(stocksWithMarketCap, etfs) {
    // Combine for visualization (ETFs with uniform size)
    const bubbleData = stocksWithMarketCap.concat(etfs.map(d => ({
        ...d,
        marketCap: d3.mean(stocksWithMarketCap.map(s => s.marketCap)) // Use average for ETFs
    })));

    // Get unique sectors
    const sectors = [...new Set(bubbleData.map(d => d.sector))].sort();

    // Color scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Size scale for bubbles
    const sizeScale = d3.scaleSqrt()
        .domain([0, d3.max(bubbleData, d => d.marketCap)])
        .range([10, 80]);

    // Create nodes for force simulation
    const nodes = bubbleData.map(d => ({
        ...d,
        x: width / 2,
        y: height / 2,
        vx: 0,
        vy: 0
    }));

    // Create force simulation
    simulation = d3.forceSimulation(nodes)
        .force('x', d3.forceX(d => {
            const sectorIndex = sectors.indexOf(d.sector);
            return (sectorIndex / (sectors.length - 1 || 1)) * width;
        }).strength(0.1))
        .force('y', d3.forceY(height / 2).strength(0.05))
        .force('collide', d3.forceCollide(d => sizeScale(d.marketCap) + 2))
        .force('charge', d3.forceManyBody().strength(-30))
        .on('tick', ticked);

    // Create bubble groups
    const bubbles = svg.selectAll('.bubble')
        .data(nodes, d => d.ticker)
        .enter()
        .append('g')
        .attr('class', 'bubble')
        .attr('data-ticker', d => d.ticker);

    // Add circles
    bubbles.append('circle')
        .attr('r', d => sizeScale(d.marketCap))
        .attr('fill', d => colorScale(d.sector))
        .attr('stroke', 'white')
        .attr('stroke-width', 2)
        .on('mouseover', function(event, d) {
            if (d.marketCap && stocks.find(s => s.ticker === d.ticker).marketCap !== null) {
                showTooltip(event, d);
            }
        })
        .on('mouseout', hideTooltip)
        .on('click', function(event, d) {
            event.stopPropagation();
            highlightBubbleAndRow(d.ticker);
        });

    // Add labels (ticker symbols)
    bubbles.append('text')
        .attr('class', 'bubble-label')
        .attr('dy', '0.3em')
        .text(d => d.ticker)
        .attr('fill', 'white')
        .attr('font-weight', 'bold')
        .attr('font-size', '11px')
        .attr('pointer-events', 'none');

    // Update positions on simulation tick
    function ticked() {
        bubbles.attr('transform', d => `translate(${d.x},${d.y})`);
    }

    // Create legend
    const legend = d3.select('#legend');
    sectors.forEach(sector => {
        const item = legend.append('div')
            .attr('class', 'legend-item');
        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', colorScale(sector));
        item.append('span')
            .text(sector);
    });
}

function createTable(stocks) {
    const tbody = d3.select('#table-body');
    const rows = tbody.selectAll('tr')
        .data(stocks, d => d.ticker)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            highlightBubbleAndRow(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.name);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => {
        if (d.marketCap === null) return 'N/A';
        return formatMarketCap(d.marketCap);
    });
}

function formatMarketCap(value) {
    if (value >= 1e12) return (value / 1e12).toFixed(2) + 'T';
    if (value >= 1e9) return (value / 1e9).toFixed(2) + 'B';
    if (value >= 1e6) return (value / 1e6).toFixed(2) + 'M';
    return value.toFixed(0);
}

function showTooltip(event, d) {
    const stock = stocks.find(s => s.ticker === d.ticker);
    if (!stock || stock.marketCap === null) return;

    tooltip.classed('visible', true)
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 10) + 'px')
        .html(`
            <strong>${d.ticker}</strong><br/>
            ${d.name}<br/>
            ${d.sector}
        `);
}

function hideTooltip() {
    tooltip.classed('visible', false);
}

function highlightBubbleAndRow(ticker) {
    // Clear previous highlights
    d3.selectAll('circle.highlighted').classed('highlighted', false);
    d3.selectAll('tr.highlighted').classed('highlighted', false);

    // Highlight bubble
    d3.selectAll(`[data-ticker="${ticker}"] circle`)
        .classed('highlighted', true);

    // Highlight table row
    const row = d3.select(`tr[data-ticker="${ticker}"]`);
    row.classed('highlighted', true);

    // Scroll table row into view
    const element = document.querySelector(`tr[data-ticker="${ticker}"]`);
    if (element) {
        element.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
}

// Clear highlights on background click
d3.select('body').on('click', function() {
    d3.selectAll('circle.highlighted').classed('highlighted', false);
    d3.selectAll('tr.highlighted').classed('highlighted', false);
});
EOF
",
      "duration": 0.1
    }
  ],
  "task_complete": false
}
